import{_ as e,o as n,c as a,a7 as i}from"./chunks/framework.CWfAgRyf.js";const u=JSON.parse('{"title":"Inventory Transactions","description":"Inventory Transactions are a system used in Axolotl-PM for grouping changes to inventories.","frontmatter":{"title":"Inventory Transactions","outline":"deep","description":"Inventory Transactions are a system used in Axolotl-PM for grouping changes to inventories.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/plugin-docs/inventory-transactions"}]]},"headers":[],"relativePath":"docs/developers/plugin-docs/inventory-transactions.md","filePath":"docs/developers/plugin-docs/inventory-transactions.md","lastUpdated":null}'),o={name:"docs/developers/plugin-docs/inventory-transactions.md"};function s(r,t,c,l,d,h){return n(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="inventory-transactions" tabindex="-1">Inventory Transactions <a class="header-anchor" href="#inventory-transactions" aria-label="Permalink to &quot;Inventory Transactions&quot;">​</a></h1><p>Inventory transactions are a system used to group changes to inventories, dropped items or other item stack locations. This system is used to provide a coherent view of activity in inventories caused by players, and to prevent cheating or creating/destroying items in multiplayer races.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>A standard inventory transaction is valid when the following conditions are met:</p><ul><li>The computed balance of the transaction is zero. This means: <ul><li>Every input must be matched by an equal number of identical outputs.</li><li>No extra items can be created (outputs without a balancing input)</li><li>No items can be destroyed (inputs without a balancing output)</li><li>Item userdata may not change on any item (custom names, lore, etc)</li></ul></li><li>The transaction must have at least 1 action.</li><li>All actions in the transaction must consider themselves valid. This includes checks such as validating that the input item stack for a slot change matches the existing stack in the inventory.</li></ul><h2 id="inventory-actions" tabindex="-1">Inventory actions <a class="header-anchor" href="#inventory-actions" aria-label="Permalink to &quot;Inventory actions&quot;">​</a></h2><p>An inventory action describes a single change to an item stack involved in the transaction. It has two primary components:</p><ul><li>Input (for validation): The item stack that should exist in the target location before the transaction takes place.</li><li>Output (for execution): The item stack that will be set into the target location once the transaction is completed.</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>A transaction is composed of an <strong>unordered set</strong> of inventory actions. The system is <strong>explicitly designed NOT to care about ordering</strong>, so your plugin should also not depend on any ordering.</p></div><h3 id="inventory-action-types" tabindex="-1">Inventory action types <a class="header-anchor" href="#inventory-action-types" aria-label="Permalink to &quot;Inventory action types&quot;">​</a></h3><p>There are several types of inventory actions which provide different methods of modifying the balance of a transaction.</p><h4 id="slot-change" tabindex="-1">Slot change <a class="header-anchor" href="#slot-change" aria-label="Permalink to &quot;Slot change&quot;">​</a></h4><p>A standard change in an inventory or container, e.g. a chest. The target location is a specific slot number in the inventory. To be valid, the input item for this action type must match the item in the inventory at the point of validation.</p><h4 id="drop-item" tabindex="-1">Drop item <a class="header-anchor" href="#drop-item" aria-label="Permalink to &quot;Drop item&quot;">​</a></h4><p>An item stack dropped into the world as an entity. This has no validation criteria other than the usual transaction balancing requirements.</p><h4 id="creative-inventory" tabindex="-1">Creative inventory <a class="header-anchor" href="#creative-inventory" aria-label="Permalink to &quot;Creative inventory&quot;">​</a></h4><p>An item stack being created or destroyed. This action type is only legal when the source player is in creative mode (and the item must exist in the creative inventory when creating items).</p>',17)])])}const v=e(o,[["render",s]]);export{u as __pageData,v as default};
